const SOURCE_VERSION = 'v1.4.7.2-domain'

function normalizeFieldDepthSemanticConflict(extra: Record<string, unknown>) {
  if (extra.depthProfileSource !== 'v1.4.7.2-field_management_depth_profile') return extra

  const durationContributionMode = String(extra.durationContributionMode ?? '').trim()
  const relationRole = String(extra.relationRole ?? '').trim()
  const executionNature = String(extra.executionNature ?? '').trim()
  const semanticClosureMode = executionNature === 'document_record'
    ? 'record_only'
    : executionNature === 'handover_milestone' || relationRole === 'handover'
      ? 'handover_marker'
      : ''
  const isExplicitNonDuration = durationContributionMode !== ''
    && durationContributionMode !== 'duration_bearing'
  const isNonDurationClosure = isExplicitNonDuration
    || semanticClosureMode !== ''
  if (!isNonDurationClosure) return extra

  const {
    depthProfileSource,
    durationContributionMode: _durationContributionMode,
    executionNature: _executionNature,
    processDepthRole,
    scheduleTrustClassification,
    ...rest
  } = extra
  const normalizedDurationContributionMode = semanticClosureMode || durationContributionMode
  const normalizedExecutionNature = semanticClosureMode === 'record_only'
    ? 'document_record'
    : semanticClosureMode === 'handover_marker'
      ? 'handover_milestone'
      : executionNature

  return {
    ...rest,
    durationContributionMode: normalizedDurationContributionMode,
    executionNature: normalizedExecutionNature,
    depthControlSource: rest.depthControlSource ?? depthProfileSource,
    processDepthRole: processDepthRole === 'field_duration_work' ? 'field_control_point' : processDepthRole,
    scheduleTrustClassification: scheduleTrustClassification === 'field_duration_work_anchor'
      ? 'field_semantic_control_point'
      : scheduleTrustClassification,
  }
}

function inferClosureCoverageSemanticRole(extra: Record<string, unknown>): CoverageProcessSemanticRole | null {
  const durationContributionMode = String(extra.durationContributionMode ?? '').trim()
  const relationRole = String(extra.relationRole ?? '').trim()
  const documentEvidenceRole = String(extra.documentEvidenceRole ?? '').trim()

  if (
    durationContributionMode === 'handover_marker'
    || relationRole === 'handover'
    || documentEvidenceRole === 'handover_document'
  ) {
    return 'handover_closeout'
  }
  if (durationContributionMode === 'record_only' || relationRole === 'evidence') return 'document_record'
  return null
}

function normalizeClosureSemanticGovernance(extra: Record<string, unknown>) {
  if (
    extra.coverageSupplementSemanticGovernance
    || extra.coverageProcessSemanticRole
  ) {
    return extra
  }

  const role = inferClosureCoverageSemanticRole(extra)
  if (!role) return extra

  return {
    ...extra,
    coverageProcessSemanticRole: role,
    coverageSupplementSemanticGovernance: 'field_semantic_thickness_v1',
  }
}

function metadata(domainScope: string, extra: Record<string, unknown> = {}) {
  const normalizedExtra = normalizeClosureSemanticGovernance(
    normalizeFieldDepthSemanticConflict(normalizeClosureSemanticGovernance(extra)),
  )
  return {
    evidenceLevel: 'A',
    verificationStatus: 'verified',
    applicableScope: domainScope,
    domainTemplateSource: 'v1.4.7.2-domain',
    templateLayer: 'domain_template_seed',
    supportsAutonomousUpgrade: true,
    upgradeBoundary: 'domain_seed_only',
    historyFeedbackPolicy: {
      mode: 'candidate_only',
      target: 'duration_dependency_and_process_pack_candidates',
      directSeedMutation: false,
    },
    workEnvironment: inferWorkEnvironment(domainScope, normalizedExtra),
    ...normalizedExtra,
  }
}

function mergeEvidenceRefs(left: unknown, right: Array<Record<string, unknown>>) {
  const leftRefs = Array.isArray(left) ? left.filter((item) => item && typeof item === 'object') : []
  const seen = new Set<string>()
  const result: Array<Record<string, unknown>> = []
  for (const ref of [...leftRefs, ...right]) {
    const key = `${String((ref as any).code ?? '')}:${String((ref as any).level ?? '')}:${String((ref as any).ref ?? '')}`
    if (seen.has(key)) continue
    seen.add(key)
    result.push(ref as Record<string, unknown>)
  }
  return result
}

function sourceStandardEvidenceRef(sourceStandard: string, domainScope: string) {
  return {
    code: sourceStandard,
    level: 'standard',
    ref: sourceStandard,
    rationale: `${domainScope} template is governed by ${sourceStandard}.`,
  }
}

function hasExplicitPlanDisplayMetadata(extra: Record<string, unknown> = {}) {
  return Boolean(
    extra.planItemKind
      || extra.scheduleParticipation
      || extra.progressMode
      || extra.criticalPathEligible !== undefined
      || extra.scopeExpansionMode
      || extra.planItemTags,
  )
}

function pickPlanDisplayMetadata(extra: Record<string, unknown> = {}) {
  const picked: Record<string, unknown> = {}
  for (const key of ['planItemKind', 'scheduleParticipation', 'progressMode', 'criticalPathEligible', 'scopeExpansionMode', 'planItemTags']) {
    if (extra[key] !== undefined) picked[key] = extra[key]
  }
  return picked
}

function pickChildSemanticContextMetadata(extra: Record<string, unknown> = {}) {
  const picked: Record<string, unknown> = {}
  for (const key of [
    'coverageProcessSemanticRole',
    'coverageSupplementSemanticGovernance',
    'coverageSupplementProfile',
    'coverageSupplementBoundary',
    'realProjectCoverageSource',
  ]) {
    if (extra[key] !== undefined) picked[key] = extra[key]
  }
  return picked
}

const DEPENDENCY_REFERENCE_FIELD_PAIRS = [
  ['referencedCoreQualityCodes', 'semanticReferencedCoreQualityCodes'],
  ['referencedMilestoneCodes', 'semanticReferencedMilestoneCodes'],
  ['referencedSiteManagementCodes', 'semanticReferencedSiteManagementCodes'],
  ['referencedDangerControlCodes', 'semanticReferencedDangerControlCodes'],
  ['referencedQualityResponsibilityCodes', 'semanticReferencedQualityResponsibilityCodes'],
  ['referencedDocumentCommercialCodes', 'semanticReferencedDocumentCommercialCodes'],
  ['referencedSpecialtyCodes', 'semanticReferencedSpecialtyCodes'],
] as const

function readReferenceCodeList(value: unknown): string[] {
  const rawValues = Array.isArray(value) ? value : String(value ?? '').split(/[,\s]+/)
  return [...new Set(rawValues.map((item) => String(item ?? '').trim()).filter(Boolean))]
}

function isExecutableReferenceCode(code: string) {
  return /-P\d{2}(?:-S\d{2})?$/.test(code)
}

function mergeReferenceCodeList(left: unknown, right: string[]) {
  return [...new Set([...readReferenceCodeList(left), ...right])]
}

function splitExecutableAndSemanticReferences(metadata: Record<string, unknown>) {
  const next = { ...metadata }
  for (const [dependencyField, semanticField] of DEPENDENCY_REFERENCE_FIELD_PAIRS) {
    const codes = readReferenceCodeList(next[dependencyField])
    if (!codes.length) continue

    const executableCodes = codes.filter(isExecutableReferenceCode)
    const semanticCodes = codes.filter((code) => !isExecutableReferenceCode(code))

    if (executableCodes.length > 0) {
      next[dependencyField] = executableCodes
    } else {
      delete next[dependencyField]
    }

    if (semanticCodes.length > 0) {
      next[semanticField] = mergeReferenceCodeList(next[semanticField], semanticCodes)
    }
  }
  return next
}

function planDisplayMetadata(input: {
  planItemKind: WbsTemplatePlanItemKind
  scheduleParticipation?: WbsTemplateScheduleParticipation
  progressMode?: WbsTemplateProgressMode
  criticalPathEligible?: boolean
  scopeExpansionMode?: string
  planItemTags?: string[]
}) {
  return {
    planItemKind: input.planItemKind,
    scheduleParticipation: input.scheduleParticipation ?? 'normal',
    progressMode: input.progressMode ?? (
      input.planItemKind === 'inspection_task'
        ? 'event_triggered'
        : input.planItemKind === 'document_task'
          ? 'upload_triggered'
          : input.planItemKind === 'milestone'
            ? 'binary'
            : input.planItemKind === 'linked_projection'
              ? 'inherited'
              : 'manual'
    ),
    criticalPathEligible: input.criticalPathEligible ?? (
      input.planItemKind === 'work_task'
      || input.planItemKind === 'management_task'
      || input.planItemKind === 'inspection_task'
      || input.planItemKind === 'milestone'
      || input.planItemKind === 'safety_control'
    ),
    scopeExpansionMode: input.scopeExpansionMode ?? 'project',
    planItemTags: input.planItemTags ?? [],
  }
}

