function coverageSemanticMetadata(role: CoverageProcessSemanticRole, extra: Record<string, unknown> = {}) {
  const preset = COVERAGE_PROCESS_SEMANTIC_PRESETS[role]
  return {
    ...planDisplayMetadata({
      planItemKind: preset.planItemKind,
      progressMode: preset.progressMode,
      criticalPathEligible: preset.criticalPathEligible,
      scopeExpansionMode: 'project_or_zone',
    }),
    relationRole: preset.relationRole,
    durationContributionMode: preset.durationContributionMode,
    executionNature: preset.executionNature,
    qualityControlRole: preset.qualityControlRole,
    safetyControlRole: preset.safetyControlRole,
    inspectionAcceptanceRole: preset.inspectionAcceptanceRole,
    documentEvidenceRole: preset.documentEvidenceRole,
    commercialControlRole: preset.commercialControlRole,
    managementControlRole: preset.managementControlRole,
    coverageProcessSemanticRole: role,
    coverageSupplementSemanticGovernance: 'field_semantic_thickness_v1',
    ...extra,
  }
}

