function inferCoverageProcessSemanticRole(profile: CoverageProcessProfile, index: number, processName: string): CoverageProcessSemanticRole {
  const sequenceRole = COVERAGE_PROFILE_SEQUENCE_ROLES[profile]?.[index] ?? 'physical_execution'

  if (includesAny(processName, ['\u5b8c\u6210\u9762\u4fdd\u62a4\u548c\u79fb\u4ea4\u7b7e\u8ba4', '\u9a8c\u6536\u8d44\u6599', '\u9a8c\u6536\u79fb\u4ea4', '\u8ffd\u6eaf\u8d44\u6599\u5f52\u6863', '\u6295\u8fd0\u9a8c\u6536', '\u8fd0\u7ef4\u79fb\u4ea4', '\u7ae3\u5de5\u9a8c\u6536', '\u6279\u91cf\u9a8c\u6536\u79fb\u4ea4', '\u9a8c\u6536\u548c\u79fb\u4ea4', '\u5f00\u901a\u63a5\u9a73\u548c\u79fb\u4ea4', '\u6295\u4ea7\u79fb\u4ea4', '\u8fd0\u884c\u57f9\u8bad\u548c\u4e13\u9879\u79fb\u4ea4', '\u63a5\u7ba1\u79fb\u4ea4', '\u7ef4\u4fdd\u63a5\u53e3', '\u4ea4\u4ed8', '\u5907\u6848'])) {
    return 'handover_closeout'
  }
  if (includesAny(processName, ['\u95ee\u9898\u6574\u6539', '\u6574\u6539', '\u9500\u9879', '\u7f3a\u9677', '\u504f\u5dee', '\u590d\u6d4b\u653e\u884c', '\u5f02\u5e38\u5904\u7406', '\u5f02\u5e38\u4f1a\u5546'])) {
    return 'rectification_closeout'
  }
  if (includesAny(processName, ['\u76d1\u6d4b', '\u89c2\u6d4b', '\u62a5\u8b66\u9608\u503c', '\u6c89\u964d', '\u4f4d\u79fb', '\u8f74\u529b\u63a7\u5236'])) {
    return 'monitoring_control'
  }
  if (includesAny(processName, ['\u5b89\u5168\u68c0\u67e5', '\u8054\u5408\u68c0\u67e5', '\u9a8c\u6536\u914d\u5408', '\u536b\u751f\u8bb8\u53ef\u9a8c\u6536', '\u4e3b\u7ba1\u90e8\u95e8\u9a8c\u6536'])) {
    return 'inspection_test'
  }
  if (includesAny(processName, ['\u590d\u9a8c', '\u590d\u8bd5', '\u9690\u853d', '\u7ae3\u5de5\u6574\u4f53\u53d8\u5f62\u6d4b\u91cf\u9a8c\u6536', '\u54c1\u724c\u8fd0\u8425\u65b9\u6807\u51c6\u9a8c\u6536'])) {
    return 'inspection_test'
  }
  if (includesAny(processName, ['\u8fdb\u573a\u9a8c\u6536', '\u6750\u6599\u8bbe\u5907\u8fdb\u573a', '\u8bbe\u5907\u6750\u6599\u8fdb\u573a', '\u6750\u6599\u6784\u4ef6\u8fdb\u573a', '\u5de5\u5382\u9a8c\u6536', '\u5f00\u7bb1\u9a8c\u6536', '\u5230\u573a\u62bd\u68c0', '\u6750\u6599\u5c01\u6837'])) {
    return 'material_acceptance'
  }
  if (includesAny(processName, ['\u7b2c\u4e09\u65b9\u68c0\u6d4b', '\u68c0\u6d4b', '\u8bd5\u9a8c', '\u6d4b\u8bd5', '\u6821\u9a8c', 'FAT', 'IQ/OQ/PQ', 'SAT', '\u63a2\u4f24', '\u6027\u80fd', '\u8054\u8c03', '\u8bd5\u8fd0'])) {
    return sequenceRole === 'physical_execution' ? 'physical_execution' : 'inspection_test'
  }
  if (index === 0 || includesAny(processName, ['\u6df1\u5316', '\u56fe\u7eb8', '\u65b9\u6848', '\u8fb9\u754c\u590d\u6838', '\u6761\u4ef6', '\u53c2\u6570', '\u6e05\u5355', '\u754c\u9762', '\u63a5\u53e3\u786e\u8ba4', '\u590d\u6838', '\u786e\u8ba4', '\u4ea4\u5e95', 'URS'])) {
    return sequenceRole === 'physical_execution' ? 'technical_preparation' : sequenceRole
  }
  if (includesAny(processName, ['\u5b89\u88c5', '\u65bd\u5de5', '\u540a\u88c5', '\u5236\u4f5c', '\u96c6\u6210', '\u8c03\u8bd5', '\u8fde\u63a5', '\u8bd5\u8fd0\u884c', '\u8fd0\u8f93', '\u5806\u653e', '\u4fdd\u62a4', '\u9884\u88c5', '\u94fa\u8bbe', '\u63a5\u5165', '\u90e8\u7f72'])) {
    return 'physical_execution'
  }

  return sequenceRole
}

function coverageProcessMetadataFor(profile: CoverageProcessProfile, index: number, processName: string) {
  if (profile === 'prefab' && processName.includes('装配率计算边界和构件清单复核')) {
    return coverageSemanticMetadata('inspection_test', {
      coverageSupplementProfile: profile,
      coverageSupplementProcessIndex: index + 1,
      qualityControlRole: 'precondition_control',
      inspectionAcceptanceRole: 'special_acceptance',
      documentEvidenceRole: 'inspection_record',
      managementControlRole: 'technical_control',
      criticalPathEligible: true,
    })
  }
  if (profile === 'prefab' && processName.includes('预制构件生产运输安装资料归集')) {
    return coverageSemanticMetadata('inspection_test', {
      coverageSupplementProfile: profile,
      coverageSupplementProcessIndex: index + 1,
      qualityControlRole: 'acceptance_gate',
      inspectionAcceptanceRole: 'special_acceptance',
      documentEvidenceRole: 'inspection_record',
      managementControlRole: 'handover_control',
      criticalPathEligible: true,
    })
  }
  if (profile === 'prefab' && processName.includes('第三方装配率评估现场核查')) {
    return coverageSemanticMetadata('inspection_test', {
      coverageSupplementProfile: profile,
      coverageSupplementProcessIndex: index + 1,
      qualityControlRole: 'acceptance_gate',
      inspectionAcceptanceRole: 'third_party_test',
      documentEvidenceRole: 'test_report',
      managementControlRole: 'handover_control',
      criticalPathEligible: true,
    })
  }
  if (profile === 'prefab' && processName.includes('装配率评估报告确认')) {
    return coverageSemanticMetadata('inspection_test', {
      coverageSupplementProfile: profile,
      coverageSupplementProcessIndex: index + 1,
      qualityControlRole: 'acceptance_gate',
      inspectionAcceptanceRole: 'special_acceptance',
      documentEvidenceRole: 'test_report',
      managementControlRole: 'handover_control',
      criticalPathEligible: true,
    })
  }
  if (
    profile === 'tod'
    && includesAny(processName, [
      '轨行区隔离防护',
      '工器具编号登记',
      '夜间天窗作业面隔离防护',
      '轨行区限界复核和运营设施保护',
      '作业完成清场检查',
      '接触网第三轨隔离解除',
    ])
  ) {
    return coverageSemanticMetadata('physical_execution', {
      coverageSupplementProfile: profile,
      coverageSupplementProcessIndex: index + 1,
      safetyControlRole: 'safety_hold_point',
      managementControlRole: 'interface_control',
      criticalPathEligible: true,
    })
  }
  if (
    profile === 'mic'
    && includesAny(processName, [
      '吊机站位地耐力',
      '吊具吊索卸扣编号',
      '指挥信号联调',
      '试吊起升',
      '风速监测和停吊条件',
      '正式起吊',
      '旁站问题整改',
      '整栋功能回归和消防联动验收配合',
    ])
  ) {
    return coverageSemanticMetadata('physical_execution', {
      coverageSupplementProfile: profile,
      coverageSupplementProcessIndex: index + 1,
      safetyControlRole: 'safety_hold_point',
      managementControlRole: 'interface_control',
      criticalPathEligible: true,
    })
  }
  const role = inferCoverageProcessSemanticRole(profile, index, processName)
  return coverageSemanticMetadata(role, {
    coverageSupplementProfile: profile,
    coverageSupplementProcessIndex: index + 1,
  })
}

function coverageInspectionAcceptanceRoleForText(text: string) {
  if (includesAny(text, ['\u7b2c\u4e09\u65b9', '\u59d4\u6258\u68c0\u6d4b', '\u68c0\u6d4b\u62a5\u544a', '\u590d\u68c0\u62a5\u544a'])) return 'third_party_test'
  if (includesAny(text, ['\u6750\u6599', '\u8bbe\u5907', '\u8fdb\u573a', '\u5230\u573a\u62bd\u68c0', '\u5de5\u5382\u9a8c\u6536', '\u5f00\u7bb1\u9a8c\u6536'])) return 'material_retest'
  if (includesAny(text, ['\u4e13\u9879\u9a8c\u6536', '\u4e13\u9879\u79fb\u4ea4', '\u6295\u8fd0\u9a8c\u6536', '\u7ae3\u5de5\u9a8c\u6536', '\u6279\u91cf\u9a8c\u6536'])) return 'special_acceptance'
  return 'self_check'
}

function coverageDocumentEvidenceRoleForInspectionText(text: string) {
  if (includesAny(text, ['\u68c0\u6d4b', '\u8bd5\u9a8c', '\u6d4b\u8bd5', '\u6821\u9a8c', '\u68c0\u6f0f', '\u63a2\u4f24', '\u590d\u6d4b', '\u590d\u68c0', '\u62a5\u544a'])) return 'test_report'
  if (includesAny(text, ['\u9a8c\u6536', '\u68c0\u67e5', '\u62bd\u67e5', '\u6838\u9a8c', '\u590d\u6838'])) return 'inspection_record'
  return 'technical_record'
}

function coverageInspectionDocumentSemanticMetadata(text: string) {
  return coverageSemanticMetadata('document_record', {
    qualityControlRole: 'acceptance_gate',
    inspectionAcceptanceRole: coverageInspectionAcceptanceRoleForText(text),
    documentEvidenceRole: coverageDocumentEvidenceRoleForInspectionText(text),
    managementControlRole: includesAny(text, ['\u95ee\u9898', '\u6574\u6539', '\u7f3a\u9677', '\u9500\u9879']) ? 'issue_rectification' : 'handover_control',
  })
}

function coverageTechnicalPreparationWithInspectionContextMetadata(text: string) {
  return coverageSemanticMetadata('technical_preparation', {
    inspectionAcceptanceRole: coverageInspectionAcceptanceRoleForText(text),
    documentEvidenceRole: coverageDocumentEvidenceRoleForInspectionText(text),
  })
}

function inferCoverageActivityStepSemanticMetadata(name: string, metadataExtra: Record<string, unknown> = {}) {
  const isCoverageSupplement = Boolean(metadataExtra.coverageProcessSemanticRole || metadataExtra.coverageSupplementSemanticGovernance)
  if (!isCoverageSupplement) return {}

  const parentRole = String(metadataExtra.coverageProcessSemanticRole ?? '') as CoverageProcessSemanticRole
  const text = String(name ?? '')

  if (
    includesAny(text, ['\u786e\u8ba4', '\u590d\u6838', '\u6838\u67e5', '\u6838\u9a8c', '\u4f5c\u4e1a\u6761\u4ef6', '\u63a5\u53e3\u6761\u4ef6', '\u6750\u6599\u8bbe\u5907', '\u6d4b\u7ed8\u7f16\u53f7', '\u6837\u677f\u786e\u8ba4', '\u8be6\u56fe\u8282\u70b9', '\u63aa\u65bd\u8bbe\u7f6e', '\u8282\u70b9\u5904\u7406', '\u8fde\u63a5\u65bd\u5de5', '\u8054\u52a8\u6d4b\u8bd5'])
    && includesAny(text, ['\u9a8c\u6536', '\u68c0\u67e5', '\u68c0\u6d4b', '\u8bd5\u9a8c', '\u6d4b\u8bd5', '\u590d\u9a8c', '\u590d\u8bd5', '\u590d\u6d4b', '\u8054\u52a8', '\u8054\u8c03', '\u9690\u853d'])
  ) {
    return coverageTechnicalPreparationWithInspectionContextMetadata(text)
  }
  if (includesAny(text, ['\u9a8c\u6536\u7ed3\u8bba\u7b7e\u8ba4', '\u4e13\u9879\u9a8c\u6536\u79fb\u4ea4', '\u5f52\u6863\u79fb\u4ea4', '\u8fbe\u6210\u8bb0\u5f55\u5f52\u6863', '\u6295\u8fd0\u9a8c\u6536', '\u8fd0\u7ef4\u79fb\u4ea4'])) {
    return coverageSemanticMetadata('handover_closeout')
  }
  if (includesAny(text, ['\u95ee\u9898\u6e05\u5355\u6838\u67e5', '\u95ee\u9898\u6574\u6539', '\u6574\u6539\u8d23\u4efb', '\u6574\u6539\u590d\u67e5', '\u6574\u6539\u95ed\u5408', '\u6302\u724c\u9a8c\u6536', '\u590d\u67e5\u590d\u6d4b', '\u7f3a\u9879\u8865\u6b63', '\u7f3a\u9677\u6574\u6539', '\u9500\u9879'])) {
    return coverageSemanticMetadata('rectification_closeout')
  }
  if (includesAny(text, ['\u9a8c\u6536\u6761\u4ef6\u6838\u67e5', '\u73b0\u573a\u62bd\u67e5\u590d\u6838', '\u73b0\u573a\u590d\u67e5\u590d\u6d4b', '\u73b0\u573a\u68c0\u67e5\u6267\u884c', '\u8d28\u91cf\u5b89\u5168\u590d\u67e5', '\u5b9e\u6d4b\u5b9e\u91cf', '\u529f\u80fd\u590d\u6838', '\u529f\u80fd\u6d4b\u8bd5', '\u6c14\u5bc6', '\u6d01\u51c0', '\u6d4b\u8bd5\u6267\u884c', '\u68c0\u6d4b', '\u8bd5\u9a8c', '\u590d\u6d4b', '\u590d\u67e5', '\u68c0\u67e5', '\u62bd\u68c0'])) {
    return coverageSemanticMetadata('inspection_test')
  }
  if (includesAny(text, ['\u7b7e\u8ba4\u5f52\u6863', '\u7b7e\u8ba4\u95ed\u5408', '\u95ed\u5408\u7b7e\u8ba4', '\u8d44\u6599\u5f52\u6863', '\u8bb0\u5f55\u5f52\u6863', '\u62a5\u544a\u5f52\u6863', '\u8d44\u6599\u6e05\u5355\u6838\u67e5', '\u8d44\u6599\u6761\u4ef6\u6838\u67e5', '\u8d44\u6599\u6838\u9a8c', '\u53f0\u8d26\u95ed\u5408', '\u8bb0\u5f55', '\u62a5\u544a', '\u8ffd\u6eaf\u8d44\u6599', '\u786e\u8ba4\u8bb0\u5f55'])) {
    return includesAny(text, ['\u9a8c\u6536', '\u68c0\u67e5', '\u68c0\u6d4b', '\u8bd5\u9a8c', '\u6d4b\u8bd5', '\u590d\u6838', '\u590d\u6d4b', '\u62bd\u68c0', '\u590d\u68c0'])
      ? coverageInspectionDocumentSemanticMetadata(text)
      : coverageSemanticMetadata('document_record')
  }
  if (
    includesAny(text, ['\u4f5c\u4e1a\u6761\u4ef6\u590d\u6838', '\u63a5\u53e3\u6761\u4ef6\u590d\u6838', '\u73b0\u573a\u6216\u63a5\u53e3\u590d\u6838', '\u8d23\u4efb\u5355\u4f4d\u590d\u6838', '\u6761\u4ef6\u6838\u67e5', '\u6d4b\u70b9\u5e03\u8bbe', '\u8fb9\u754c\u590d\u6838'])
    && includesAny(text, ['\u9a8c\u6536', '\u68c0\u67e5', '\u68c0\u6d4b', '\u8bd5\u9a8c', '\u6d4b\u8bd5', '\u590d\u6838', '\u590d\u6d4b', '\u62bd\u68c0', '\u6821\u9a8c', '\u8054\u8c03'])
  ) {
    return coverageTechnicalPreparationWithInspectionContextMetadata(text)
  }
  if (includesAny(text, ['\u4f5c\u4e1a\u6761\u4ef6\u590d\u6838', '\u63a5\u53e3\u6761\u4ef6\u590d\u6838', '\u73b0\u573a\u6216\u63a5\u53e3\u590d\u6838', '\u8d23\u4efb\u5355\u4f4d\u590d\u6838', '\u6761\u4ef6\u6838\u67e5', '\u6d4b\u70b9\u5e03\u8bbe', '\u8fb9\u754c\u590d\u6838'])) {
    return coverageSemanticMetadata('technical_preparation')
  }
  if (includesAny(text, ['\u8fc7\u7a0b\u65bd\u5de5', '\u5b9e\u4f53\u65bd\u5de5', '\u5b89\u88c5\u65bd\u5de5', '\u540a\u88c5\u5b9a\u4f4d', '\u73b0\u573a\u5feb\u63a5', '\u63aa\u65bd\u8bbe\u7f6e', '\u8303\u56f4\u548c\u73b0\u573a\u6e05\u7406'])) {
    return coverageSemanticMetadata(parentRole === 'physical_execution' ? 'physical_execution' : 'technical_preparation')
  }

  if (parentRole && COVERAGE_PROCESS_SEMANTIC_PRESETS[parentRole]) {
    return coverageSemanticMetadata(parentRole)
  }
  return {}
}


function inferPlanDisplayMetadata(domainScope: string, processName: string, extra: Record<string, unknown> = {}) {
  if (hasExplicitPlanDisplayMetadata(extra)) return {}
  if (domainScope === siteManagementScope) {
    const inspection = /验收|检查|核验|测试|巡检|复查|联调|监测/.test(processName)
    const management = /确认|组织|计划|方案|交底|台账|建档|配置|接入|协调|移交/.test(processName)
    return planDisplayMetadata({
      planItemKind: inspection ? 'inspection_task' : management ? 'management_task' : 'work_task',
      progressMode: inspection ? 'event_triggered' : 'manual',
      scopeExpansionMode: 'project',
    })
  }
  if (domainScope === dangerControlScope) {
    return planDisplayMetadata({
      planItemKind: 'safety_control',
      progressMode: 'event_triggered',
      scopeExpansionMode: 'triggered_object',
      planItemTags: ['危大'],
    })
  }
  if (domainScope === qualityResponsibilityScope) {
    return planDisplayMetadata({
      planItemKind: 'inspection_task',
      progressMode: 'event_triggered',
      scopeExpansionMode: 'referenced_work_or_project',
    })
  }
  if (domainScope === projectMilestoneScope) {
    const isLinkedProjection = Boolean(extra.acceptanceLinkRule || extra.isAcceptanceMilestone)
    return planDisplayMetadata({
      planItemKind: isLinkedProjection ? 'linked_projection' : 'milestone',
      progressMode: 'binary',
      scopeExpansionMode: 'project',
      planItemTags: ['关键节点'],
    })
  }
  if (domainScope === documentCommercialScope) {
    const commercial = /商务|签证|变更|计量|付款|结算|索赔|认质认价|价格|价款|审减/.test(processName)
    return planDisplayMetadata({
      planItemKind: commercial ? 'commercial_task' : 'document_task',
      progressMode: commercial ? 'manual' : 'upload_triggered',
      criticalPathEligible: commercial,
      scopeExpansionMode: 'project',
    })
  }
  return planDisplayMetadata({
    planItemKind: 'work_task',
    progressMode: 'manual',
    scopeExpansionMode: 'building',
  })
}

