export function defaultWbsTemplateGenerationPolicy(templateGroup: WbsTemplateDomainGroup): WbsTemplateGenerationPolicy {
  if (templateGroup === 'site_management' || templateGroup === 'quality_responsibility' || templateGroup === 'project_milestone' || templateGroup === 'document_commercial_support') return 'default_selected'
  if (templateGroup === 'danger_control') return 'triggered'
  return TRIGGERED_SPECIALTY_GROUPS.has(templateGroup) ? 'triggered' : 'explicit'
}

export function getDefaultWbsTemplateTriggerKeywords(templateGroup: WbsTemplateDomainGroup) {
  return DEFAULT_WBS_TEMPLATE_TRIGGER_KEYWORDS[templateGroup] ?? []
}

