function nonFieldManagementProcessMetadata(
  role: string,
  options: {
    mode?: DurationContributionMode
    nature?: ExecutionNature
    planItemKind?: WbsTemplatePlanItemKind
    progressMode?: WbsTemplateProgressMode
    scheduleParticipation?: WbsTemplateScheduleParticipation
    tags?: string[]
    scopeExpansionMode?: string
  } = {},
): Record<string, unknown> {
  return {
    ...planDisplayMetadata({
      planItemKind: options.planItemKind ?? 'management_task',
      scheduleParticipation: options.scheduleParticipation,
      progressMode: options.progressMode ?? 'manual',
      criticalPathEligible: false,
      scopeExpansionMode: options.scopeExpansionMode ?? 'project',
      planItemTags: options.tags,
    }),
    durationContributionMode: options.mode ?? 'embedded_check',
    executionNature: options.nature ?? 'management_action',
    processDepthRole: role,
    fieldDepthHardeningExempt: true,
    scheduleTrustClassification: 'non_field_control_or_projection',
  }
}

function includesAny(value: string, keywords: string[]) {
  return keywords.some((keyword) => value.includes(keyword))
}

function activityStepsFor(processName: string) {
  // === 危大工程专项模板精确规则 ===
  if (includesAny(processName, ['危大工程识别', '清单确认'])) return ['危大范围识别和清单编制', '信息核对和清单确认签认']
  if (includesAny(processName, ['专项施工方案编制']) && !includesAny(processName, ['审核', '审批'])) return ['方案编制', '内部校审']
  if (includesAny(processName, ['方案审核审批', '审核审批'])) return ['方案审核', '方案审批签认']
  if (includesAny(processName, ['专家论证组织', '专家论证', '意见闭合'])) return ['论证准备和专家组织', '论证意见闭合和方案修订']
  if (includesAny(processName, ['方案交底', '人员资格核查']) && includesAny(processName, ['核查', '交底'])) return ['方案交底执行', '人员资格核查和签字确认']
  if (includesAny(processName, ['过程监测巡查', '旁站记录']) && includesAny(processName, ['监测', '巡查', '旁站'])) return ['现场监测和巡查', '旁站记录和问题上报']
  if (includesAny(processName, ['专项验收', '资料归档']) && includesAny(processName, ['验收', '归档'])) return ['专项检查和验收', '资料组卷和归档']
  // 安全教育/责任
  if (includesAny(processName, ['安全生产责任制', '目标分解签认'])) return ['责任制编制和目标分解', '签认和上墙公示']
  if (includesAny(processName, ['三级安全教育', '转岗新工艺培训'])) return ['教育大纲和培训执行', '考核和建档签认']
  if (includesAny(processName, ['安全技术交底签字', '分部分项安全技术交底']) && includesAny(processName, ['签字'])) return ['安全技术交底执行', '双方签字确认']
  if (includesAny(processName, ['班前安全活动', '作业许可确认'])) return ['班前活动记录和作业许可核查', '违章纠偏和整改']
  if (includesAny(processName, ['安全资金使用计划', '专职安全员配置'])) return ['资金计划编制和安全员配置核查', '配置确认记录']
  if (includesAny(processName, ['应急预案物资', '演练记录'])) return ['应急预案和物资准备', '演练执行和记录评估']

  // === 分层级：复杂测试/调试/联调/验收 → 3步（必须在施工之前） ===
  if (includesAny(processName, ['试验', '测试', '调试', '联调', '检测', '试运行', '模拟运行', '送检', '取样', '试块', '试件', '耐压', '绝缘', '试运转', '检漏', '校验', '计量', '采集', '探伤', '试验', '灌水', '通球', '试压', '检验'])) {
    return [`${processName}方案或条件确认`, `${processName}测试执行和过程记录`, `${processName}问题整改闭合和报告`]
  }

  // === 方案/审批/论证/交底/培训/教育 → 2步（施工前） ===
  if (includesAny(processName, ['方案编制', '方案审批', '审核审批', '方案审核', '专家论证', '方案交底', '技术交底', '教育培训', '安全教育', '技术培训', '演示', '交底'])) {
    return [`${processName}编制或准备`, `${processName}签认确认`]
  }

  // === 材料/设备/进场/复验 → 3步（施工前） ===
  if (includesAny(processName, ['材料', '设备', '进场', '复验', '核验', '开箱'])) {
    return [`${processName}资料核验`, `${processName}外观数量检查`, `${processName}验收记录签认`]
  }

  // === 验收/归档/闭合 → 2步（施工前） ===
  if (includesAny(processName, ['验收', '归档', '闭合', '签认', '挂牌', '建档'])) {
    return [`${processName}检查验收`, `${processName}签认归档`]
  }

  // === 监测/巡查/旁站/巡检/检查/实测/普查/排查 → 2步（施工前） ===
  if (includesAny(processName, ['监测', '巡查', '旁站', '巡检', '检查', '监控', '实测实量', '复查', '复测', '普查', '排查', '抽样', '抽检', '整改', '监督'])) {
    return [`${processName}现场检查执行`, `${processName}检查记录和问题上报`]
  }

  // === 确认/复核/核查/识别/核对/预审/深化 → 2步（施工前） ===
  if (includesAny(processName, ['确认', '复核', '核查', '识别', '核对', '校核', '校审', '预审', '审批', '深化', '排砖', '排版'])) {
    return [`${processName}条件或数据核查`, `${processName}确认记录`]
  }

  // === 施工安装类 → 3步 ===
  if (includesAny(processName, ['安装', '敷设', '固定', '连接', '砌筑', '施工', '搭设', '搭拆', '拆改', '铺装', '摊铺', '开挖', '支护', '回填', '压实', '碾压', '浇筑', '焊接', '吊装', '吊挂', '张拉', '喷涂', '涂刷', '铺设', '密封', '封堵', '防腐', '保温', '防水', '凿除', '切割', '钻孔', '设置', '封顶', '封闭', '补强', '修补', '固化', '收口', '收边', '注浆', '压浆', '灌浆', '灌注', '围挡', '贴砖', '找平', '找坡', '粉刷', '涂装', '粘贴', '锚固', '植筋', '绑扎', '浇筑', '拌合', '夯实', '振捣', '凿毛', '剔凿', '打磨', '开槽', '开孔', '塞缝', '顶砌', '斜砌', '支撑', '排水', '冲洗', '打胶', '粘锚', '碳纤维', '包钢', '粘钢', '基层处理', '处理', '平衡', '配合', '预留', '控制', '导改', '协调', '恢复', '完成', '贯通', '封闭', '构造柱', '圈梁', '过梁', '钢筋', '模板', '端接', '模块'])) {
    return [`${processName}作业面准备`, `${processName}过程施工`, `${processName}班组自检记录`]
  }

  // === 测量/放线/定位/标高 → 2步 ===
  if (includesAny(processName, ['测量', '放线', '定位', '标高', '放样', '排布'])) {
    return [`${processName}实测实量`, `${processName}测量成果记录`]
  }

  // === 清理/退场/拆除 → 2步 ===
  if (includesAny(processName, ['清理', '退场', '拆除', '清槽', '清洁'])) {
    return [`${processName}范围和现场清理`, `${processName}验收确认记录`]
  }

  // === 保护/防护/覆盖 → 2步 ===
  if (includesAny(processName, ['保护', '防护', '覆盖', '封样', '养护'])) {
    return [`${processName}措施设置`, `${processName}检查记录`]
  }

  // === 组织/协调/计划/接驳/接入/移交/切换/资料/商务 → 2步 ===
  if (includesAny(processName, ['组织', '协调', '计划', '接驳', '接入', '移交', '切换', '配置', '登记', '发放', '公示', '建档', '冻结', '回写', '模拟', '演练', '交接', '测算', '申报', '报送', '台账', '汇总', '归集', '清单', '通知', '跟踪', '取证', '报告', '批复', '自查', '保修', '维修', '证据', '认质认价', '派单', '打包', '提交', '审批', '报送', '流转', '会签', '分派', '统计', '布置', '记录', '组卷', '维护', '运行', '配合', '预留', '保险', '办理', '总结', '更新', '结算', '报审'])) {
    return [`${processName}组织或计划确认`, `${processName}执行和记录签认`]
  }

  // === 兜底 ===
  return [`${processName}作业条件复核`, `${processName}过程质量检查`, `${processName}验收记录签认`]
}

