function domainItemCodeFromProcessCode(stableCode: string) {
  return stableCode.replace(/-P\d+$/, '')
}

function domainActivityStepNeedsMinimumFive(stableCode: string) {
  const itemCode = domainItemCodeFromProcessCode(stableCode)
  return DOMAIN_ACTIVITY_STEP_MINIMUM_FIVE_ITEM_CODES.has(itemCode)
    || DOMAIN_ACTIVITY_STEP_MINIMUM_FIVE_CODE_PREFIXES.some((prefix) => stableCode.startsWith(prefix))
}

function domainComplexActivityStepTargetFor(stableCode: string, domainScope: string, processName: string) {
  const context = `${domainScope} ${processName}`
  if (stableCode.includes('-UTILITY-')) return null
  if (DOMAIN_ACTIVITY_STEP_TARGET_SEVEN_CODE_PREFIXES.some((prefix) => stableCode.startsWith(prefix))) return 7
  if (DOMAIN_ACTIVITY_STEP_TARGET_SIX_CODE_PREFIXES.some((prefix) => stableCode.startsWith(prefix))) return 6
  if (includesAny(context, ['洁净', '数据中心', '装配式', '深基坑', '基坑', 'TOD', 'MiC', '模块', '文保', '改造', '钢结构'])) return 6
  return null
}

function domainActivityTargetStepCount(domainScope: string, stableCode: string, processName: string, steps: string[]) {
  const context = `${domainScope} ${processName}`
  const complexTarget = domainComplexActivityStepTargetFor(stableCode, domainScope, processName)
  if (complexTarget) return Math.max(complexTarget, steps.length)
  if (domainActivityStepNeedsMinimumFive(stableCode)) return 5
  if (domainScope === projectMilestoneScope) return 5
  if (
    domainScope === siteManagementScope
    || domainScope === documentCommercialScope
    || domainScope === qualityResponsibilityScope
  ) return 5
  if (includesAny(context, ['FIR-', 'ELV-', 'FAC-', 'STL-', 'PFB-', 'CLN-', 'CDF-', '消防', '火灾自动报警', '电梯', '幕墙', '钢结构', '装配式', '洁净', '人防', '深基坑', '高支模', '系统调试', '联动调试', '数据中心'])) return 5
  if (includesAny(context, ['ELE-', 'HVA-', 'PLU-', '安装', '施工', '系统', '调试', '联调', '测试', '检测', '试验', '试运行', '核相', '送电', '验收', '防水', '保温', '防火封堵', '防雷', '防腐', '管道', '风管', '阀门', '传感器', '计量点', '排油烟', '补风', '深化', '桥架', '母线', '电缆', '配电', '开关柜', '吊装', '灌浆', '压浆', '注浆', '监测', '焊接', '吊顶', '涂饰', '精装', '临电', '临水', '临时消防'])) return 4
  if (steps.length <= 2 && includesAny(processName, ['确认', '复核', '检查', '验收', '移交', '交接', '深化', '排布', '样板'])) return 3
  return steps.length
}

function completeDomainActivitySteps(processName: string, steps: string[], targetStepCount: number) {
  if (steps.length >= targetStepCount) return steps
  const completedSteps = [...steps]
  const supplementalSteps = [
    `${processName}接口条件复核`,
    `${processName}过程实施记录`,
    `${processName}关键控制点复查`,
    `${processName}实测数据或试运行记录复核`,
    `${processName}质量安全复查`,
    `${processName}问题整改闭合`,
    `${processName}验收移交签认`,
  ]

  for (const step of supplementalSteps) {
    if (completedSteps.length >= targetStepCount) break
    if (!completedSteps.includes(step)) completedSteps.push(step)
  }

  return completedSteps
}

function dangerManagementActivitySteps(processName: string, targetStepCount: number) {
  if (includesAny(processName, ['危大工程识别', '清单确认'])) {
    return [
      `${processName}触发条件核查`,
      `${processName}危大类别分级确认`,
      `${processName}责任单位会签`,
      `${processName}清单版本确认`,
      `${processName}清单归档`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['专项施工方案编制', '专项施工方案审核审批'])) {
    return [
      `${processName}编制依据和工程参数复核`,
      `${processName}方案内容完整性核查`,
      `${processName}审核审批流转`,
      `${processName}审批意见闭合`,
      `${processName}方案版本归档`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['专家论证组织', '专家论证', '意见闭合'])) {
    return [
      `${processName}论证资料准备`,
      `${processName}专家意见确认`,
      `${processName}论证意见接收`,
      `${processName}方案修订闭合`,
      `${processName}论证资料归档`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['方案交底', '人员资格核查'])) {
    return [
      `${processName}交底对象和资格清单核查`,
      `${processName}安全技术交底记录`,
      `${processName}人员资格证照复核`,
      `${processName}签认台账闭合`,
      `${processName}资料归档`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['过程监测巡查', '旁站记录'])) {
    return [
      `${processName}监测巡查计划确认`,
      `${processName}旁站检查记录`,
      `${processName}异常预警复核`,
      `${processName}问题整改复查`,
      `${processName}台账归档`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['第三方监测', '成果接收'])) {
    return [
      `${processName}委托条件确认`,
      `${processName}监测成果接收`,
      `${processName}异常数据复核`,
      `${processName}处置闭合记录`,
      `${processName}报告归档`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['专项验收', '资料归档'])) {
    return [
      `${processName}验收条件核查`,
      `${processName}联合验收组织`,
      `${processName}问题整改复查`,
      `${processName}验收结论签认`,
      `${processName}资料归档`,
    ].slice(0, targetStepCount)
  }

  return null
}

function milestoneActivitySteps(processName: string, targetStepCount: number) {
  return [
    `${processName}前置条件核查`,
    `${processName}责任单位确认`,
    `${processName}节点状态确认`,
    `${processName}关联事实或资料链接`,
    `${processName}达成记录归档`,
  ].slice(0, targetStepCount)
}

function documentOrGateActivitySteps(processName: string, targetStepCount: number) {
  if (includesAny(processName, ['资料核验', '资料复核', '资料组卷', '资料归档', '报告归档', '记录归档', '台账闭合', '运行维护资料组卷', '图纸会审', '清单复核'])) {
    return [
      `${processName}资料清单核查`,
      `${processName}责任单位复核`,
      `${processName}缺项补正`,
      `${processName}签认闭合`,
      `${processName}归档移交`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['验收'])) {
    return [
      `${processName}验收条件核查`,
      `${processName}现场抽查复核`,
      `${processName}问题整改复查`,
      `${processName}验收结论签认`,
      `${processName}记录归档`,
    ].slice(0, targetStepCount)
  }

  if (includesAny(processName, ['问题闭合', '整改闭合', '整改复测', '复查', '复测', '销项', '节点签认'])) {
    return [
      `${processName}问题清单核查`,
      `${processName}现场复查复测`,
      `${processName}整改责任确认`,
      `${processName}闭合签认`,
      `${processName}记录归档`,
    ].slice(0, targetStepCount)
  }

  return null
}

