function normalizeDomainEnglishProcessTerms(name: string) {
  if (!/[A-Za-z]/.test(name)) return name
  return DOMAIN_ENGLISH_PROCESS_TERM_REPLACEMENTS.reduce((currentName, [pattern, replacement]) => (
    currentName.replace(pattern, replacement)
  ), name)
    .replace(/\s+(现场作业|现场条件复核|验收移交签认|条件复核|作业|签认|复测作业|整改作业|闭合作业)$/g, '$1')
    .replace(/\s+(和|或|与|及)\s+/g, '$1')
    .replace(/\s{2,}/g, ' ')
    .trim()
}

function normalizeDomainProcessName(name: string) {
  const replacements: Array<[RegExp, string]> = [
    [/\bscope, interface, and workface readiness review\b/gi, '范围界面和作业面条件复核'],
    [/\bworkface readiness review\b/gi, '作业面条件复核'],
    [/\breadiness review\b/gi, '条件复核'],
    [/\bmaterial and equipment receiving installation work\b/gi, '材料设备进场安装作业'],
    [/\bprimary civil or structural construction work\b/gi, '主体土建或结构施工'],
    [/\bMEP and intelligent-system installation work\b/gi, '机电和智能化安装作业'],
    [/\bcommissioning, function-test, and correction work\b/gi, '调试功能测试和整改作业'],
    [/\bcommissioning, function-test\b/gi, '调试功能测试'],
    [/\bfield retest and defect closeout work\b/gi, '现场复测和缺陷闭合作业'],
    [/\bdefect closeout work\b/gi, '缺陷闭合作业'],
    [/\bcloseout work\b/gi, '闭合作业'],
    [/\bretest work\b/gi, '复测作业'],
    [/\bcorrection work\b/gi, '整改作业'],
    [/\binstallation work\b/gi, '安装作业'],
    [/\bacceptance handover\b/gi, '验收移交'],
    [/\brunbook signoff\b/gi, '运行手册签认'],
    [/\boperation-interface signoff\b/gi, '运行界面签认'],
    [/\bacceptance signoff\b/gi, '验收签认'],
    [/\bsignoff\b/gi, '签认'],
    [/\bcloseout\b/gi, '闭合'],
    [/\bwork\b/gi, '作业'],
  ]

  const workflowNormalized = replacements.reduce((currentName, [pattern, replacement]) => (
    currentName.replace(pattern, replacement)
  ), name)
  return normalizeDomainEnglishProcessTerms(workflowNormalized)
}

function localizeDomainProcessName(name: string, metadata: Record<string, unknown> = {}) {
  if (/\p{Script=Han}/u.test(name)) return name

  const depthRole = String(metadata.processDepthRole ?? metadata.process_depth_role ?? '')
  if (depthRole === 'field_control_point') return `${name}现场条件复核`
  if (depthRole === 'field_acceptance_gate') return `${name}验收移交签认`
  return `${name}现场作业`
}

function processPack(
  stablePrefix: string,
  sourceStandard: string,
  sourceClauseRef: string,
  domainScope: string,
  role: string,
  specs: DomainProcessSpec[],
) {
  return specs.map((spec, index) => {
    const normalized = typeof spec === 'string' ? { name: spec } : spec
    const normalizedName = localizeDomainProcessName(
      normalizeDomainProcessName(normalized.name),
      normalized.metadata,
    )
    const processCode = `${stablePrefix}-P${String(index + 1).padStart(2, '0')}`
    return process(
      processCode,
      normalizedName,
      normalized.sourceStandard ?? sourceStandard,
      normalized.sourceClauseRef ?? sourceClauseRef,
      domainScope,
      normalized.steps ?? activityStepsFor(normalizedName),
      {
        role: normalized.role ?? role,
        preconditions: normalized.preconditions,
        acceptance: normalized.acceptance,
        metadata: normalized.metadata,
      },
    )
  })
}

function itemPack(
  stableCode: string,
  name: string,
  sourceStandard: string,
  sourceClauseRef: string,
  domainScope: string,
  role: string,
  specs: DomainProcessSpec[],
  metadataExtra: Record<string, unknown> = {},
) {
  const windowSpecList = specs as PackageWindowSpecList
  const packageWindowsByProcessIndex = windowSpecList.__packageWindowsByProcessIndex
  const resolvedSpecs = withDomainProcessMetadata(domainScope, stableCode, specs)
  const windowedProcessSpecs = packageWindowsByProcessIndex
    ? withPackageWindows(resolvedSpecs, packageWindowsByProcessIndex)
    : resolvedSpecs
  const nonFieldProcessMetadata = nonFieldDepthProcessMetadata(stableCode)
  const processSpecs = Object.keys(nonFieldProcessMetadata).length > 0
    ? windowedProcessSpecs.map((spec) => {
      const normalized = typeof spec === 'string' ? { name: spec } : spec
      return {
        ...normalized,
        metadata: {
          ...(normalized.metadata ?? {}),
          ...nonFieldProcessMetadata,
        },
      }
    })
    : windowedProcessSpecs
  return item(
    stableCode,
    name,
    sourceStandard,
    sourceClauseRef,
    domainScope,
    processPack(stableCode, sourceStandard, sourceClauseRef, domainScope, role, processSpecs),
    {
      ...metadataExtra,
      ...nonFieldDepthItemMetadata(stableCode),
    },
  )
}

function schedulablePhysicalProcessSpec(
  name: string,
  complexity: SpecialtyDepthProfile['complexity'] = 'complex',
): Exclude<DomainProcessSpec, string> {
  return {
    name,
    metadata: {
      durationContributionMode: 'duration_bearing',
      executionNature: 'physical_work',
      processDepthRole: 'field_duration_work',
      processComplexity: complexity,
      depthProfileSource: 'v1.4.7.2-field_management_depth_profile',
      scheduleTrustClassification: 'field_duration_work_anchor',
    },
  }
}

function processSpecName(spec: DomainProcessSpec) {
  return typeof spec === 'string' ? spec : spec.name
}

function deepenFieldActivitySteps(
  specs: DomainProcessSpec[],
  context: string,
  anchors: {
    pointList: string
    circuit: string
    wiring: string
    dispatchChannel: string
    protectionSetting: string
    backfeedPermit: string
    handover: string
  },
): DomainProcessSpec[] {
  return specs.map((spec) => {
    const name = processSpecName(spec)
    const normalized = typeof spec === 'string' ? { name } : spec
    return {
      ...normalized,
      steps: normalized.steps ?? [
        `${context}${name}现场条件、${anchors.pointList}点表和${anchors.circuit}回路复核`,
        `${context}${name}${anchors.wiring}接线、接口映射和作业记录`,
        `${context}${name}${anchors.dispatchChannel}调度通道、联动链路和通信状态核验`,
        `${context}${name}${anchors.protectionSetting}保护定值、倒送电许可和安全边界确认`,
        `${context}${name}缺陷复测闭合、证据归档和${anchors.handover}移交签认`,
      ],
      metadata: {
        ...(normalized.metadata ?? {}),
        fieldSemanticDepthSource: 'native_specialty_chinese_activity_steps',
        fieldSemanticAnchors: [
          anchors.pointList,
          anchors.circuit,
          anchors.wiring,
          anchors.dispatchChannel,
          anchors.protectionSetting,
          anchors.backfeedPermit,
          '缺陷复测',
          anchors.handover,
        ],
      },
    }
  })
}

