function contextualizedSpecialtyProcessSpecs(context: string, specs: DomainProcessSpec[]): DomainProcessSpec[] {
  return specs.map((spec, index) => {
    const normalized = typeof spec === 'string' ? { name: spec } : spec
    return {
      ...normalized,
      name: index === 0 ? `专项扩展场景条件复核: ${normalized.name}` : normalized.name,
      acceptance: normalized.acceptance?.map((item) => `${context}: ${item}`),
      metadata: {
        ...(normalized.metadata ?? {}),
        contextualizedFromProcessChain: context,
        processNamingPolicy: 'preserve_field_action_name',
      },
    }
  })
}

