type CoverageSupplementPack = {
  code: string
  name: string
  sourceStandard: string
  sourceClauseRef: string
  role: string
  processes: DomainProcessSpec[]
  metadata?: Record<string, unknown>
}

function coverageProcess(name: string, metadataExtra: Record<string, unknown> = {}): DomainProcessSpec {
  return Object.keys(metadataExtra).length > 0 ? { name, metadata: metadataExtra } : name
}

function supplementPack(
  code: string,
  name: string,
  sourceStandard: string,
  sourceClauseRef: string,
  role: string,
  processes: DomainProcessSpec[],
  metadataExtra: Record<string, unknown> = {},
): CoverageSupplementPack {
  return {
    code,
    name,
    sourceStandard,
    sourceClauseRef,
    role,
    processes: processes.map((processSpec) => typeof processSpec === 'string' ? coverageProcess(processSpec) : processSpec),
    metadata: metadataExtra,
  }
}

function coverageSupplementItemPacks(domainScope: string, packs: CoverageSupplementPack[]) {
  return packs.map((pack) => itemPack(
    pack.code,
    pack.name,
    pack.sourceStandard,
    pack.sourceClauseRef,
    domainScope,
    pack.role,
    pack.processes,
    {
      realProjectCoverageSource: 'wbs-template-real-project-coverage-2026-05-22:15.3',
      coverageSupplement: true,
      coverageSupplementBoundary: 'template_task_and_semantic_attributes_only',
      ...pack.metadata,
    },
  ))
}

function promotedCoverageSourceClauseRef(sourceClauseRef: string) {
  return sourceClauseRef === '真实项目覆盖补充'
    ? '§15.3 真实项目正式深度扩展'
    : sourceClauseRef
}

function promotedCoverageItemPacks(
  domainScope: string,
  packs: CoverageSupplementPack[],
  codeBase: string,
) {
  return packs.map((pack, index) => {
    const stableCode = `${codeBase}-${String(index + 1).padStart(2, '0')}`
    return itemPack(
      stableCode,
      pack.name,
      pack.sourceStandard,
      promotedCoverageSourceClauseRef(pack.sourceClauseRef),
      domainScope,
      pack.role,
      pack.processes,
      {
        realProjectCoverageSource: 'wbs-template-real-project-coverage-2026-05-22:15.3',
        realProjectCoveragePromoted: true,
        nativeSpecialtyDepth: true,
        templateDepthMaturity: 'native_real_project_promoted',
        promotedFromCoverageCode: pack.code,
        promotionPolicy: 'coverage_supplement_promoted_to_formal_specialty_division',
        coverageSupplementBoundary: 'template_task_and_semantic_attributes_only',
        ...pack.metadata,
        coverageSupplement: false,
      },
    )
  })
}

function promotedCoverageDivision(
  stableCode: string,
  name: string,
  sourceStandard: string,
  sourceClauseRef: string,
  domainScope: string,
  packs: CoverageSupplementPack[],
) {
  return division(stableCode, name, sourceStandard, sourceClauseRef, domainScope, [
    subDivision(
      `${stableCode}-01`,
      `${name}清单`,
      sourceStandard,
      sourceClauseRef,
      domainScope,
      promotedCoverageItemPacks(domainScope, packs, `${stableCode}-01`),
    ),
  ])
}

function promotedCoverageDivisions(
  sourceStandard: string,
  domainScope: string,
  specs: Array<{
    code: string
    name: string
    packs: CoverageSupplementPack[]
    sourceClauseRef?: string
  }>,
) {
  return specs
    .filter((spec) => spec.packs.length > 0)
    .map((spec) => promotedCoverageDivision(
      spec.code,
      spec.name,
      sourceStandard,
      spec.sourceClauseRef ?? '§15.3 真实项目正式深度扩展',
      domainScope,
      spec.packs,
    ))
}

function filterCoveragePacksByProfile(packs: CoverageSupplementPack[], profiles: CoverageProcessProfile[]) {
  const profileSet = new Set(profiles)
  return packs.filter((pack) => profileSet.has(String(pack.metadata?.coverageSupplementPackProfile ?? '') as CoverageProcessProfile))
}

function coverageSupplementDivision(
  stableCode: string,
  name: string,
  sourceStandard: string,
  sourceClauseRef: string,
  domainScope: string,
  packs: CoverageSupplementPack[],
) {
  return division(stableCode, name, sourceStandard, sourceClauseRef, domainScope, [
    subDivision(
      `${stableCode}-01`,
      `${name}清单`,
      sourceStandard,
      sourceClauseRef,
      domainScope,
      coverageSupplementItemPacks(domainScope, packs),
    ),
  ])
}

function realProjectCoverageSupplementDivisions(templateGroup: WbsTemplateDomainGroup, domainScope: string): ChinaTemplateCatalogNode[] {
  switch (templateGroup) {
    default:
      return []
  }
}

function domainCatalog(options: {
  templateId: string
  templateCode: string
  templateName: string
  templateGroup: WbsTemplateDomainGroup
  packType?: WbsTemplatePackType
  generationPolicy?: WbsTemplateGenerationPolicy
  triggerKeywords?: string[]
  domainScope: string
  applicableScope: string[]
  sourceStandards: string[]
  sourceStandard: string
  divisions: ChinaTemplateCatalogNode[]
}): DomainWbsTemplateCatalog {
  const supplementDivisions = realProjectCoverageSupplementDivisions(options.templateGroup, options.domainScope)
  return {
    templateId: options.templateId,
    templateCode: options.templateCode,
    templateName: options.templateName,
    packType: options.packType ?? 'specialty',
    templateGroup: options.templateGroup,
    generationPolicy: options.generationPolicy ?? defaultWbsTemplateGenerationPolicy(options.templateGroup),
    triggerKeywords: options.triggerKeywords ?? getDefaultWbsTemplateTriggerKeywords(options.templateGroup),
    domainScope: options.domainScope,
    applicableScope: options.applicableScope,
    sourceStandards: options.sourceStandards,
    sourceStandard: options.sourceStandard,
    sourceVersion: SOURCE_VERSION,
    catalogLevel: 'national',
    evidenceStatus: 'verified',
    reviewNeeded: false,
    webVerified: true,
    divisions: [...options.divisions, ...supplementDivisions],
  }
}

