function coverageExplicitProcesses(profile: CoverageProcessProfile, processes: DomainProcessSpec[]): DomainProcessSpec[] {
  return processes.map((processSpec, index) => {
    const processName = typeof processSpec === 'string' ? processSpec : processSpec.name
    const processMetadata = typeof processSpec === 'string' ? {} : processSpec.metadata ?? {}
    return coverageProcess(
      processName,
      {
        ...coverageProcessMetadataFor(profile, index, processName),
        coverageProcessDepthSource: 'native_differentiated_real_project_processes',
        ...processMetadata,
      },
    )
  })
}

