function clinicalEvidenceProcesses(
  processes: string[],
  evidence: {
    fieldEvidenceKeywords: string[]
    handoverEvidenceType: string
    acceptanceCheckpoints: string[]
  },
): DomainProcessSpec[] {
  return processes.map((name, index) => {
    if (index === 0) {
      return {
        name,
        metadata: {
          fieldEvidenceKeywords: evidence.fieldEvidenceKeywords,
        },
      }
    }
    if (index === processes.length - 1) {
      return {
        name,
        metadata: {
          handoverEvidenceType: evidence.handoverEvidenceType,
          acceptanceCheckpoints: evidence.acceptanceCheckpoints,
        },
      }
    }
    return name
  })
}

