    if (subject.includes('带运营')) return ['运营动线和施工边界确认', '临时围挡和隔音防尘施工', '消防疏散和临时导视调整', '夜间窗口期作业审批', '每日巡查和扰民问题闭合', '阶段性作业面交还']
    if (subject.includes('临时支撑') || subject.includes('卸载')) return ['支撑卸载方案和监测点确认', '支撑构件进场复验', '临时支撑定位安装', '分级卸载和位移观测', '受力转换复核', '支撑拆除条件验收']
