function coverageDifferentiatedProcessNames(profile: CoverageProcessProfile, subject: string): DomainProcessSpec[] | null {
  if (profile === 'building_detail') {
    if (subject.includes('楼层') || subject.includes('穿插')) return [
      '楼层结构实测实量与拉通排查',
      '二次结构砌筑作业面移交',
      '机电预留预埋和管线点位核对',
      '防水吊顶精装样板穿插条件确认',
      '楼层材料垂直运输和管井周转路径复核',
      '各专业日清日结节奏复盘',
      '穿插问题清单和责任人闭合',
      '楼层穿插作业面移交签认',
    ]
    if (subject.includes('充电') || subject.includes('车库')) return [
      '充电车位分区和设备基础定位复核',
      '桥架管线路由和配电箱位置复核',
      '地面坡度排水和接地点位确认',
      '预留套管桥架子框和防水封堵',
      '地库涂料划线和车位标识协调',
      '配电接入绝缘接地和通电条件复核',
      '充电桩安装前土建机电联合验收',
      '运维编号管线图和移交台账签认',
    ]
    return coverageProfileProcesses(profile, subject).map((spec) => typeof spec === 'string' ? spec : spec.name)
  }
  if (profile === 'prefab') return prefabDifferentiatedProcesses(subject)
  if (profile === 'cleanroom') return clnDifferentiatedProcesses(subject)
  if (profile === 'data_center') return dtcDifferentiatedProcesses(subject)
  if (profile === 'industrial_cleanroom') return icrDifferentiatedProcesses(subject)
  if (profile === 'steel') return steelDifferentiatedProcesses(subject)
  if (profile.startsWith('foundation_')) return foundationDifferentiatedProcesses(profile, subject)
  if (['renovation', 'heritage', 'campus', 'tod', 'mic', 'factory_unit', 'hotel'].includes(profile)) {
    return operationalSpecialtyDifferentiatedProcesses(profile, subject)
  }
  return null
}

function coveragePacks(
  codeBase: string,
  sourceStandard: string,
  sourceClauseRef: string,
  role: string,
  defaultProfile: CoverageProcessProfile,
  entries: CoveragePackEntry[],
  defaultMetadata: Record<string, unknown> = {},
): CoverageSupplementPack[] {
  return entries.map((entry, index) => {
    const normalized = typeof entry === 'string'
      ? { name: entry, profile: defaultProfile, metadata: {} }
      : Array.isArray(entry)
        ? { name: entry[0], profile: entry[1], metadata: entry[2] ?? {} }
        : {
            name: entry.name,
            profile: entry.profile ?? defaultProfile,
            metadata: entry.metadata ?? {},
            processes: entry.processes,
          }
    const name = normalized.name
    const profile = normalized.profile
    const entryMetadata = normalized.metadata
    const explicitProcesses = 'processes' in normalized ? normalized.processes : undefined
    const differentiatedProcessNames = explicitProcesses ?? coverageDifferentiatedProcessNames(profile, name)
    const processSpecs = differentiatedProcessNames
      ? coverageExplicitProcesses(profile, differentiatedProcessNames)
      : coverageProfileProcesses(profile, name)
    return supplementPack(
      `${codeBase}-${String(index + 1).padStart(2, '0')}`,
      name,
      sourceStandard,
      sourceClauseRef,
      role,
      processSpecs,
      {
        ...defaultMetadata,
        coverageSupplementPackProfile: profile,
        coverageProcessDepthSource: differentiatedProcessNames
          ? 'native_differentiated_real_project_processes'
          : 'coverage_profile_fallback',
        ...entryMetadata,
      },
    )
  })
}

