function domainBoundaryMetadata(domainScope: string): Record<string, unknown> {
  if (domainScope === outdoorScope || domainScope === municipalScope) {
    return {
      generationMode: 'additive_specialty_scope',
      duplicateBoundary: 'external_support_scope_not_core_quality_replacement',
      specialtyScopeBoundary: 'outdoor_municipal_external_support',
      coreQualityReplacementPolicy: 'none_additive_only',
    }
  }
  return {}
}

