function coreReplacementPolicyForItem(domainScope: string, stableCode: string) {
  const itemPolicy = CORE_REPLACEMENT_CODES_BY_ITEM_CODE_PREFIX.find(([prefix]) => stableCode.startsWith(prefix))
  if (itemPolicy) {
    return {
      codes: itemPolicy[1],
      explicitPolicy: true,
    }
  }
  return {
    codes: CORE_REPLACEMENT_CODES_BY_DOMAIN_SCOPE[domainScope],
    explicitPolicy: false,
  }
}

function normalizeProcessSpec(spec: DomainProcessSpec): Exclude<DomainProcessSpec, string> {
  return typeof spec === 'string' ? { name: spec } : spec
}

type SpecialtyDepthProfile = {
  minimumProcessCount: number
  complexity: 'standard' | 'complex' | 'critical'
  supplements: DomainProcessSpec[]
}

function semanticDurationProcess(name: string, metadataExtra: Record<string, unknown> = {}): DomainProcessSpec {
  return durationDepthSupplement(name, 'critical', {
    semanticTrustOverrideSource: 'v1.4.7.2-schedule_trust_semantic_process_profile',
    executionNature: 'physical_work',
    ...metadataExtra,
  })
}

function semanticGateProcess(name: string, metadataExtra: Record<string, unknown> = {}): DomainProcessSpec {
  return {
    name,
    metadata: {
      semanticTrustOverrideSource: 'v1.4.7.2-schedule_trust_semantic_process_profile',
      durationContributionMode: 'quality_gate',
      executionNature: 'inspection_test',
      processDepthRole: 'field_acceptance_gate',
      processComplexity: 'critical',
      ...metadataExtra,
    },
  }
}

function semanticCheckProcess(name: string, metadataExtra: Record<string, unknown> = {}): DomainProcessSpec {
  return {
    name,
    metadata: {
      semanticTrustOverrideSource: 'v1.4.7.2-schedule_trust_semantic_process_profile',
      durationContributionMode: 'embedded_check',
      executionNature: 'inspection_test',
      processDepthRole: 'field_control_point',
      processComplexity: 'critical',
      ...metadataExtra,
    },
  }
}

function semanticRecordProcess(name: string, metadataExtra: Record<string, unknown> = {}): DomainProcessSpec {
  return {
    name,
    metadata: {
      semanticTrustOverrideSource: 'v1.4.7.2-schedule_trust_semantic_process_profile',
      durationContributionMode: 'record_only',
      executionNature: 'document_record',
      processDepthRole: 'field_control_point',
      processComplexity: 'critical',
      ...metadataExtra,
    },
  }
}

function semanticHandoverProcess(name: string, handoverEvidenceType?: string, metadataExtra: Record<string, unknown> = {}): DomainProcessSpec {
  return {
    name,
    metadata: {
      semanticTrustOverrideSource: 'v1.4.7.2-schedule_trust_semantic_process_profile',
      durationContributionMode: 'quality_gate',
      executionNature: 'inspection_test',
      processDepthRole: 'field_acceptance_gate',
      processComplexity: 'critical',
      ...(handoverEvidenceType ? { handoverEvidenceType } : {}),
      ...metadataExtra,
    },
  }
}

