type ProcessEvidenceDepthProfile = {
  firstFieldEvidenceKeywords?: string[]
  terminalHandoverEvidenceType?: string
  terminalAcceptanceCheckpoints?: string[]
}

function processEvidenceDepthProfile(
  firstFieldEvidenceKeywords: string[],
  terminalHandoverEvidenceType: string,
  terminalAcceptanceCheckpoints: string[],
): ProcessEvidenceDepthProfile {
  return {
    firstFieldEvidenceKeywords,
    terminalHandoverEvidenceType,
    terminalAcceptanceCheckpoints,
  }
}

function systemProcessEvidenceDepthProfile(
  subject: string,
  firstFieldEvidenceKeywords: string[],
  terminalHandoverEvidenceType: string,
): ProcessEvidenceDepthProfile {
  return processEvidenceDepthProfile(firstFieldEvidenceKeywords, terminalHandoverEvidenceType, [
    `${subject}范围边界、点位清单和责任界面完成复核签认`,
    `${subject}材料设备进场、安装条件和样板要求记录完整`,
    `${subject}安装施工、接线接管和隐蔽影像资料闭合`,
    `${subject}单机测试、功能联调和性能参数复核通过`,
    `${subject}缺陷问题、异常告警和整改复测完成闭合`,
    `${subject}检测报告、调试记录、资产台账和培训资料归档完整`,
    `${subject}验收签认、运维账号和后续使用界面移交完成`,
  ])
}

const PROJECT_MILESTONE_ACCEPTANCE_CHECKPOINTS = [
  '里程碑触发条件、适用范围和责任单位复核完成',
  '前置审批、验收、检测、调试或移交资料清单核验完成',
  '现场实体、系统接口、运营接口或主管部门意见复核完成',
  '问题清单、整改责任、复查结论和例外事项闭合完成',
  '参建单位、主管部门、运营单位或接收方签认资料完整',
  '计划状态、基准节点、业务台账和附件索引回填完成',
  '里程碑达成记录归档并完成后续使用或移交边界确认',
]

function projectMilestoneEvidenceDepthProfile(stableCode: string, processName: string): ProcessEvidenceDepthProfile | undefined {
  if (!stableCode.startsWith('MS-')) return undefined

  const evidenceCode = stableCode
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')

  return processEvidenceDepthProfile(
    [
      processName,
      '前置条件',
      '责任单位',
      '资料清单',
      '现场或接口复核',
      '签认归档',
    ],
    `project_milestone_${evidenceCode}_evidence_closeout_handover`,
    PROJECT_MILESTONE_ACCEPTANCE_CHECKPOINTS,
  )
}

