const TERMINAL_PROCESS_NAME_KEYWORDS = [
  '验收',
  '移交',
  '交接',
  '归档',
  '资料',
  '包装保护',
  '成品保护',
  '放行',
  '签认',
  'acceptance',
  'handover',
  'hand-off',
  'handoff',
  'closeout',
  'dossier',
  'release',
  'signoff',
  'sign-off',
  'protection',
]

function isTerminalSpecialtyProcessName(name: string) {
  const normalizedName = name.toLowerCase()
  return TERMINAL_PROCESS_NAME_KEYWORDS.some((keyword) => normalizedName.includes(keyword.toLowerCase()))
}

function specialtyProcessInsertIndexForSupplement(
  result: readonly Exclude<DomainProcessSpec, string>[],
  supplement: Exclude<DomainProcessSpec, string>,
  fallbackIndex: number,
) {
  const beforeName = typeof supplement.metadata?.insertBeforeProcessName === 'string'
    ? supplement.metadata.insertBeforeProcessName
    : ''
  if (!beforeName) return fallbackIndex

  const targetIndex = result.findIndex((spec) => spec.name === beforeName)
  return targetIndex >= 0 ? targetIndex : fallbackIndex
}

function terminalSpecialtyProcessInsertIndex(specs: readonly Exclude<DomainProcessSpec, string>[]) {
  const firstTerminalIndex = specs.findIndex((spec) => isTerminalSpecialtyProcessName(spec.name))
  return firstTerminalIndex >= 0 ? firstTerminalIndex : specs.length
}

function mergeProcessEvidenceKeywords(existing: unknown, additions: string[] | undefined) {
  const merged = new Set<string>()
  if (Array.isArray(existing)) {
    for (const item of existing) {
      if (typeof item === 'string' && item.trim()) merged.add(item)
    }
  }
  for (const item of additions ?? []) {
    if (item.trim()) merged.add(item)
  }
  return Array.from(merged)
}

function applyProcessEvidenceDepthProfile(stableCode: string, specs: DomainProcessSpec[]): DomainProcessSpec[] {
  const result = specs.map(normalizeProcessSpec)
  const profile = PROCESS_EVIDENCE_DEPTH_PROFILES_BY_ITEM_CODE[stableCode]
    ?? projectMilestoneEvidenceDepthProfile(stableCode, result[0]?.name ?? stableCode)
  if (!profile) return specs

  const firstProcess = result[0]
  if (firstProcess && profile.firstFieldEvidenceKeywords?.length) {
    result[0] = {
      ...firstProcess,
      metadata: {
        ...(firstProcess.metadata ?? {}),
        fieldEvidenceKeywords: mergeProcessEvidenceKeywords(
          firstProcess.metadata?.fieldEvidenceKeywords,
          profile.firstFieldEvidenceKeywords,
        ),
      },
    }
  }

  const terminalIndex = result.length - 1
  const terminalProcess = result[terminalIndex]
  if (terminalProcess && (profile.terminalHandoverEvidenceType || profile.terminalAcceptanceCheckpoints?.length)) {
    result[terminalIndex] = {
      ...terminalProcess,
      metadata: {
        ...(terminalProcess.metadata ?? {}),
        ...(profile.terminalHandoverEvidenceType ? { handoverEvidenceType: profile.terminalHandoverEvidenceType } : {}),
        ...(profile.terminalAcceptanceCheckpoints?.length
          ? { acceptanceCheckpoints: profile.terminalAcceptanceCheckpoints }
          : {}),
      },
    }
  }

  return result
}

type PackageWindow = {
  start: number
  end: number
  role: string
}

type PackageWindowSpecList = DomainProcessSpec[] & {
  __packageWindowsByProcessIndex?: Record<number, Record<string, unknown>>
}

function packageWindow(start: number, end: number, role: string): Record<string, unknown> {
  return {
    rhythmWindowStartDay: start,
    rhythmWindowEndDay: end,
    rhythmWindowDurationDays: Math.max(1, end - start + 1),
    rhythmWindowRole: role,
    packageChildRhythmWindow: {
      startDay: start,
      endDay: end,
      durationDays: Math.max(1, end - start + 1),
      role,
      source: 'template_duration_truth_asset',
    },
  }
}

