function packageWindowByParentDays(windows: Record<number, PackageWindow>): Record<string, unknown> {
  const entries = Object.entries(windows).map(([days, window]) => [
    days,
    {
      startDay: window.start,
      endDay: window.end,
      durationDays: Math.max(1, window.end - window.start + 1),
      role: window.role,
      source: 'template_duration_truth_asset',
    },
  ])
  return {
    packageChildRhythmWindowByParentDays: Object.fromEntries(entries),
  }
}

function parentDurationTruthMetadata(
  policy: 'rhythm_package_window' | 'system_package_window' | 'specialty_package_window',
  referenceDurationDays: number,
  role: string,
): Record<string, unknown> {
  return {
    durationBoundaryPolicy: policy,
    durationBoundaryPolicySource: 'template_duration_truth_asset',
    planDurationTruthSource: 'parent_package_rhythm_window',
    referenceDurationDays,
    smartReferenceDays: referenceDurationDays,
    parentDurationTruthRole: role,
    parentDurationTruthBoundary: 'parent_window_is_plan_truth_children_are_package_windows',
  }
}

function withPackageWindowMetadata(spec: DomainProcessSpec, windowMetadata: Record<string, unknown>): DomainProcessSpec {
  const normalized = normalizeProcessSpec(spec)
  return {
    ...normalized,
    metadata: {
      ...windowMetadata,
      ...normalized.metadata,
    },
  }
}

function withPackageWindows(specs: DomainProcessSpec[], windows: Record<number, Record<string, unknown>>): DomainProcessSpec[] {
  const result = specs.map((spec, index) => (
    windows[index + 1]
      ? withPackageWindowMetadata(spec, windows[index + 1])
      : spec
  )) as PackageWindowSpecList
  Object.defineProperty(result, '__packageWindowsByProcessIndex', {
    value: windows,
    enumerable: false,
  })
  return result
}

function depthControlSupplementSemanticMetadata(
  name: string,
  metadataExtra: Record<string, unknown> = {},
): Record<string, unknown> {
  const durationContributionMode = resolveDomainActivityDurationContributionMode(name, metadataExtra)
  if (
    includesAny(name, [
      '补正作业',
      '整改作业',
      '复核作业',
      '核查作业',
      '评审作业',
    ])
  ) {
    return {}
  }
  if (durationContributionMode === 'handover_marker') return coverageSemanticMetadata('handover_closeout')
  if (durationContributionMode === 'record_only') return coverageSemanticMetadata('document_record')
  if (durationContributionMode === 'quality_gate') return coverageSemanticMetadata('inspection_test')
  return coverageSemanticMetadata('technical_preparation')
}

function depthSupplement(
  name: string,
  complexity: SpecialtyDepthProfile['complexity'],
  metadataExtra: Record<string, unknown> = {},
): DomainProcessSpec {
  const semanticMetadata = depthControlSupplementSemanticMetadata(name, metadataExtra)
  return {
    name,
    metadata: {
      ...semanticMetadata,
      depthControlSource: 'v1.4.7.2-field_management_depth_profile',
      processComplexity: complexity,
      processDepthRole: 'field_control_point',
      ...metadataExtra,
    },
  }
}

function durationDepthSupplement(
  name: string,
  complexity: SpecialtyDepthProfile['complexity'],
  metadataExtra: Record<string, unknown> = {},
): DomainProcessSpec {
  const semanticMetadata = metadataExtra.durationContributionMode === 'record_only'
    ? coverageSemanticMetadata('document_record')
    : metadataExtra.durationContributionMode === 'quality_gate'
      ? coverageSemanticMetadata('inspection_test')
      : {}
  return {
    name,
    metadata: {
      ...semanticMetadata,
      depthProfileSource: 'v1.4.7.2-field_management_depth_profile',
      durationContributionMode: 'duration_bearing',
      processComplexity: complexity,
      processDepthRole: 'field_duration_work',
      ...metadataExtra,
    },
  }
}

