function dangerClassCode(dangerType: string) {
  if (dangerType.includes('deep') || dangerType.includes('深基')) return 'deep_foundation_pit'
  if (dangerType.includes('重型') || dangerType.includes('超长') || dangerType.includes('超宽')) return 'heavy_prefab_component_hoisting'
  if (dangerType.includes('滑模') || dangerType.includes('爬模') || dangerType.includes('飞模') || dangerType.includes('隧道模') || dangerType.includes('工具式')) return 'tool_formwork'
  if (dangerType.includes('模板')) return 'high_formwork'
  if (dangerType.includes('起重') || dangerType.includes('塔吊')) return 'lifting_hoisting'
  if (dangerType.includes('scaffold') || dangerType.includes('脚手')) return 'scaffold'
  if (dangerType.includes('hoist') || dangerType.includes('升降')) return 'construction_hoist'
  if (dangerType.includes('用电')) return 'temporary_power'
  if (dangerType.includes('幕墙')) return 'curtain_wall'
  if (dangerType.includes('拆除')) return 'demolition'
  if (dangerType.includes('人工挖孔')) return 'manual_dug_pile'
  if (dangerType.includes('暗挖') || dangerType.includes('顶管') || dangerType.includes('盾构')) return 'underground_tunneling'
  if (dangerType.includes('装配式') || dangerType.includes('预制构件')) return 'prefab_component_installation'
  if (dangerType.includes('水下')) return 'underwater_work'
  if (dangerType.includes('网架') || dangerType.includes('索膜')) return 'space_frame_membrane'
  if (dangerType.includes('整体提升') || dangerType.includes('顶升') || dangerType.includes('平移') || dangerType.includes('转体')) return 'large_structure_lift_shift'
  if (dangerType.includes('新技术') || dangerType.includes('新工艺') || dangerType.includes('新材料') || dangerType.includes('新设备')) return 'new_technology_safety_review'
  if (dangerType.includes('steel') || dangerType.includes('钢结')) return 'steel_structure_hoisting'
  return 'danger_control'
}

function dangerTriggerConditions(dangerType: string, triggerCondition: string): WbsTemplateTriggerCondition[] {
  const dangerClass = dangerClassCode(dangerType)
  const conditions: WbsTemplateTriggerCondition[] = [{
    sourceField: 'engineeringObject.metadata.dangerClassCodes',
    operator: 'includes',
    value: dangerClass,
    conditionRole: 'direct_trigger',
  }]

  if (dangerClass === 'deep_foundation_pit' && triggerCondition.includes('3m')) {
    conditions.push({
      sourceField: 'engineeringObject.metadata.foundationDepthM',
      operator: '>=',
      value: 3,
      unit: 'm',
      conditionRole: 'screening',
    })
  }
  if (dangerClass === 'deep_foundation_pit' && (triggerCondition.includes('5m') || triggerCondition.includes('专家论证'))) {
    conditions.push({
      sourceField: 'engineeringObject.metadata.foundationDepthM',
      operator: '>=',
      value: 5,
      unit: 'm',
      conditionRole: 'expert_review',
    })
  }
  if (triggerCondition.includes('5m')) {
    conditions.push({ sourceField: 'engineeringObject.metadata.supportHeightM', operator: '>=', value: 5, unit: 'm', conditionRole: 'screening' })
  }
  if (triggerCondition.includes('8m')) {
    conditions.push({ sourceField: 'engineeringObject.metadata.supportHeightM', operator: '>=', value: 8, unit: 'm', conditionRole: 'expert_review' })
  }
  if (triggerCondition.includes('10m')) {
    conditions.push({ sourceField: 'engineeringObject.metadata.supportSpanM', operator: '>=', value: 10, unit: 'm', conditionRole: 'screening' })
  }
  if (triggerCondition.includes('18m')) {
    conditions.push({ sourceField: 'engineeringObject.metadata.supportSpanM', operator: '>=', value: 18, unit: 'm', conditionRole: 'expert_review' })
  }
  if (/施工总荷载10kN\/m2|施工总荷载10kN\/m²|10kN\/m2|10kN\/m²/.test(triggerCondition)) {
    conditions.push({ sourceField: 'engineeringObject.metadata.supportLoadKnPerM2', operator: '>=', value: 10, unit: 'kN/m2', conditionRole: 'screening' })
  }
  if (/施工总荷载15kN\/m2|施工总荷载15kN\/m²|15kN\/m2|15kN\/m²/.test(triggerCondition)) {
    conditions.push({ sourceField: 'engineeringObject.metadata.supportLoadKnPerM2', operator: '>=', value: 15, unit: 'kN/m2', conditionRole: 'expert_review' })
  }
  if (/集中线荷载15kN\/m|15kN\/m/.test(triggerCondition)) {
    conditions.push({ sourceField: 'engineeringObject.metadata.lineLoadKnPerM', operator: '>=', value: 15, unit: 'kN/m', conditionRole: 'screening' })
  }
  if (/集中线荷载20kN\/m|20kN\/m/.test(triggerCondition)) {
    conditions.push({ sourceField: 'engineeringObject.metadata.lineLoadKnPerM', operator: '>=', value: 20, unit: 'kN/m', conditionRole: 'expert_review' })
  }
  if (triggerCondition.includes('24m')) {
    conditions.push({ sourceField: 'engineeringObject.metadata.scaffoldHeightM', operator: '>=', value: 24, unit: 'm', conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'lifting_hoisting') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasTowerCrane', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'tool_formwork') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasToolFormwork', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'construction_hoist') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasConstructionHoist', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (triggerCondition.includes('10kV')) {
    conditions.push({ sourceField: 'engineeringObject.metadata.temporaryPowerVoltageKv', operator: '>=', value: 10, unit: 'kV', conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'curtain_wall') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasCurtainWallHighWork', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'demolition') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasDemolitionWork', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'manual_dug_pile') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasManualDugPile', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'underground_tunneling') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasUndergroundExcavationWork', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'prefab_component_installation') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasPrefabComponentInstallation', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'heavy_prefab_component_hoisting') {
    conditions.push({ sourceField: 'engineeringObject.metadata.prefabComponentMaxWeightT', operator: '>=', value: 5, unit: 't', conditionRole: 'screening' })
    conditions.push({ sourceField: 'engineeringObject.metadata.hasOversizedPrefabComponent', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'underwater_work') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasUnderwaterWork', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'space_frame_membrane') {
    conditions.push({ sourceField: 'engineeringObject.metadata.spaceFrameSpanM', operator: '>=', value: 36, unit: 'm', conditionRole: 'expert_review' })
  }
  if (dangerClass === 'large_structure_lift_shift') {
    conditions.push({ sourceField: 'engineeringObject.metadata.structureLiftWeightKn', operator: '>=', value: 1000, unit: 'kN', conditionRole: 'expert_review' })
  }
  if (dangerClass === 'new_technology_safety_review') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasNewTechnologySafetyReview', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }
  if (dangerClass === 'steel_structure_hoisting') {
    conditions.push({ sourceField: 'engineeringObject.metadata.hasLargeSpanSteelHoisting', operator: '=', value: true, conditionRole: 'direct_trigger' })
  }

  return conditions
}

function dangerTriggerMetadata(dangerType: string, triggerCondition: string) {
  const triggerConditions = dangerTriggerConditions(dangerType, triggerCondition)
  return {
    nodeRole: 'danger_control',
    branchFamily: 'danger_control',
    branchKey: dangerType,
    branchSelectionMode: 'auto_by_trigger',
    branchTriggerConditions: triggerConditions,
    siteHazardPlaceholder: {
      fieldKey: 'siteHazardDescription',
      label: '现场具体危险源描述',
      placeholder: `请补充${dangerType}在本项目的具体危险源、部位、规模、周边环境和控制要求`,
      requiredWhenTriggered: true,
      editableByProject: true,
      valueSource: 'project_site_fact',
      templateKeepsRegulatoryWording: true,
    },
    siteHazardFields: [
      {
        fieldKey: 'siteHazardDescription',
        label: '现场具体危险源描述',
        valueType: 'long_text',
        requiredWhenTriggered: true,
      },
      {
        fieldKey: 'siteHazardLocation',
        label: '危险源部位/范围',
        valueType: 'scope_reference_or_text',
        requiredWhenTriggered: false,
      },
      {
        fieldKey: 'siteHazardControlMeasures',
        label: '项目专项控制要点',
        valueType: 'long_text',
        requiredWhenTriggered: false,
      },
    ],
    hazardNarrativePolicy: 'template_standard_process_plus_project_specific_hazard_description',
    processPackLevel: 'danger_control_package',
    processGranularity: 'danger_control_management_action',
    generationMode: 'auto_by_trigger_only',
    triggerClosureRequired: true,
    duplicateBoundary: 'not_core_quality_construction_work',
    dangerTriggers: [{
      dangerType,
      triggerCondition,
      sourceStandard: DANGER_CONTROL_SOURCE_STANDARD,
      requiresSpecialScheme: true,
      requiresExpertReview: /专家论证|超过一定规模|深基坑|高大模板|悬挑|附着升降|人工挖孔|拆除/.test(triggerCondition),
    }],
    triggerRules: [{
      ruleType: 'danger_control_keyword_or_threshold',
      keywords: [dangerType],
      triggerCondition,
      triggerConditions,
      sourceStandard: DANGER_CONTROL_SOURCE_STANDARD,
    }],
    triggerConditions,
  }
}

